import type * as THREE from 'three';
import { easings } from '@react-spring/three';
import { useModelAnimation } from './useModelAnimation';
import { useModelStore } from '../stores/model-store';

interface UseLidAnimationOptions {
  actions: Record<string, THREE.AnimationAction | null>;
  groupRef: React.RefObject<THREE.Group | null>;
}

/**
 * Hook that handles lid open/close animation with easeOutBounce easing.
 * Converts boolean lidOpen state to 0-1 progress for animation.
 */
export function useLidAnimation({
  actions,
  groupRef,
}: UseLidAnimationOptions): void {
  useModelAnimation({
    actions,
    groupRef,
    clipName: 'open lid',
    getProgress: () => useModelStore.getState().lidOpen ? 1 : 0,
    config: {
      duration: 1500,
      easing: easings.easeOutBounce,
    },
  });
}
```

## Key Details
- Converts boolean `lidOpen` to number: `lidOpen ? 1 : 0`
- Uses same easing as bogie for consistency
- Clip name is 'open lid' (with space)

