}

/**
 * Hook that handles lid animation with easeOutBounce easing.
 * Converts boolean lidOpen state to 0-1 progress.
 */
export function useLidAnimation({
  actions,
  groupRef,
}: UseLidAnimationOptions): void {
  // Animated progress value (0=closed, 1=open) with easeOutBounce easing
  const progress = useSpringValue(
    useModelStore.getState().lidOpen ? 1 : 0,
    { config: { duration: 1500, easing: easings.easeOutBounce } }
  );

  // Track last state to avoid unnecessary spring updates
  const lastLidOpenRef = useRef(useModelStore.getState().lidOpen);

  // Store reference to the lid animation clip
  const lidClipRef = useRef<THREE.AnimationClip | null>(null);

  // Initialize lid animation clip
  useEffect(() => {
    const lidAction = actions['open lid'];
    if (\!lidAction) return;

    lidClipRef.current = lidAction.getClip();
    lidAction.stop();
  }, [actions]);

  // Animation frame
  useFrame(() => {
    const lidOpen = useModelStore.getState().lidOpen;
    if (lidOpen \!== lastLidOpenRef.current) {
      lastLidOpenRef.current = lidOpen;
      progress.start(lidOpen ? 1 : 0);
    }

    const clip = lidClipRef.current;
    if (\!clip || \!groupRef.current) return;

    const currentProgress = progress.get();
    const animTime = clip.duration * currentProgress;

    // Apply animation to all tracks
    for (const track of clip.tracks) {
      const [objectName, propertyName] = track.name.split('.');
      const targetObject = groupRef.current.getObjectByName(objectName);

      if (\!targetObject) continue;

      const sampledValues = sampleTrackAtTime(track, animTime);

      if (propertyName === 'position') {
        targetObject.position.set(sampledValues[0], sampledValues[1], sampledValues[2]);
      } else if (propertyName === 'quaternion') {
        targetObject.quaternion.set(sampledValues[0], sampledValues[1], sampledValues[2], sampledValues[3]);
      } else if (propertyName === 'scale') {
        targetObject.scale.set(sampledValues[0], sampledValues[1], sampledValues[2]);
      }
    }
  });
}
```

