import { easings } from '@react-spring/three';
import type * as THREE from 'three';

export interface ModelAnimationConfig {
  duration?: number;
  easing?: (t: number) => number;
}

export interface UseModelAnimationOptions {
  /** Animation actions from useAnimations hook */
  actions: Record<string, THREE.AnimationAction | null>;
  /** Reference to the group containing animated objects */
  groupRef: React.RefObject<THREE.Group | null>;
  /** Name of the animation clip to use (e.g., 'rocker', 'open lid') */
  clipName: string;
  /** Function that returns current progress (0-1) from store */
  getProgress: () => number;
  /** Optional animation config */
  config?: ModelAnimationConfig;
}

export const DEFAULT_CONFIG: ModelAnimationConfig = {
  duration: 1500,
  easing: easings.easeOutBounce,
};
```

## Implementation Steps
1. Import dependencies: useSpringValue from @react-spring/three, useFrame from @react-three/fiber, useEffect/useRef from react
2. Import sampleTrackAtTime from ../utils/animation-utils
3. Create useModelAnimation function with options parameter
4. Initialize spring with `getProgress()` initial value
5. Store clip reference using clipName to find action
6. In useFrame:
   - Check if progress changed using getProgress()
   - Start spring if changed
   - Sample clip at `clip.duration * currentProgress`
   - Apply transforms to objects

## Key Implementation Details
```typescript
export function useModelAnimation({
  actions,
  groupRef,
  clipName,
  getProgress,
  config = DEFAULT_CONFIG,
}: UseModelAnimationOptions): void {
  const { duration = 1500, easing = easings.easeOutBounce } = config;

  // Animated progress value with configured easing
  const progress = useSpringValue(getProgress(), {
    config: { duration, easing },
  });

  // Track last progress to detect changes
  const lastProgressRef = useRef(getProgress());

  // Store reference to the animation clip
  const clipRef = useRef<THREE.AnimationClip | null>(null);

  // Initialize clip
  useEffect(() => {
    const action = actions[clipName];
    if (\!action) return;

    clipRef.current = action.getClip();
    action.stop(); // Don't use mixer playback
  }, [actions, clipName]);

  // Animation frame
  useFrame(() => {
    const targetProgress = getProgress();
    if (targetProgress \!== lastProgressRef.current) {
      lastProgressRef.current = targetProgress;
      progress.start(targetProgress);
    }

    const clip = clipRef.current;
    if (\!clip || \!groupRef.current) return;

    const currentProgress = progress.get();
    const animTime = clip.duration * currentProgress;

    // Apply animation to all tracks
    for (const track of clip.tracks) {
      const [objectName, propertyName] = track.name.split('.');
      const targetObject = groupRef.current.getObjectByName(objectName);
      if (\!targetObject) continue;

      const sampledValues = sampleTrackAtTime(track, animTime);

      // Apply based on property type
      if (propertyName === 'position') {
        targetObject.position.set(sampledValues[0], sampledValues[1], sampledValues[2]);
      } else if (propertyName === 'quaternion') {
        targetObject.quaternion.set(sampledValues[0], sampledValues[1], sampledValues[2], sampledValues[3]);
      } else if (propertyName === 'scale') {
        targetObject.scale.set(sampledValues[0], sampledValues[1], sampledValues[2]);
      }
    }
  });
}
```

